import{_ as e,o as l,c as d,a2 as a}from"./chunks/framework.ClgMjOt7.js";const f=JSON.parse('{"title":"ライブ壁紙 & ウィジェット仕様","description":"ライブ壁紙サービス、画像ローテーション制御、ホーム画面ウィジェットプロバイダ","frontmatter":{"title":"ライブ壁紙 & ウィジェット仕様","description":"ライブ壁紙サービス、画像ローテーション制御、ホーム画面ウィジェットプロバイダ"},"headers":[],"relativePath":"features/wallpaper-widget.md","filePath":"features/wallpaper-widget.md","lastUpdated":1786169627000}'),o={name:"features/wallpaper-widget.md"};function i(r,t,c,n,s,g){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="ライブ壁紙-ウィジェット仕様" tabindex="-1">ライブ壁紙 &amp; ウィジェット仕様 <a class="header-anchor" href="#ライブ壁紙-ウィジェット仕様" aria-label="Permalink to &quot;ライブ壁紙 &amp; ウィジェット仕様&quot;">​</a></h1><p>Android システムと統合されたライブ壁紙およびホーム画面ウィジェットに関する詳細仕様です。</p><hr><h2 id="ライブ壁紙サービス-pallerialivewallpaperservice" tabindex="-1">ライブ壁紙サービス (<code>PalleriaLiveWallpaperService</code>) <a class="header-anchor" href="#ライブ壁紙サービス-pallerialivewallpaperservice" aria-label="Permalink to &quot;ライブ壁紙サービス (`PalleriaLiveWallpaperService`)&quot;">​</a></h2><p>Android の <code>WallpaperService</code> を拡張し、Pixiv 作品やローカル保存画像を定期的に壁紙として描画・切り替えるバックグラウンドサービスです。</p><h3 id="制御パラメータ-appsettings" tabindex="-1">制御パラメータ (<code>AppSettings</code>) <a class="header-anchor" href="#制御パラメータ-appsettings" aria-label="Permalink to &quot;制御パラメータ (`AppSettings`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">設定キー</th><th style="text-align:left;">型</th><th style="text-align:left;">初期値</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>wallpaperPlaylistEnabled</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">ライブ壁紙機能の有効化</td></tr><tr><td style="text-align:left;"><code>liveWallpaperSource</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;all&quot;</code></td><td style="text-align:left;">画像ソース (<code>all</code> / <code>bookmarks</code> / <code>folder</code>)</td></tr><tr><td style="text-align:left;"><code>liveWallpaperSourceFolder</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;&quot;</code></td><td style="text-align:left;">カスタムフォルダ指定時のローカルパス</td></tr><tr><td style="text-align:left;"><code>liveWallpaperIntervalMinutes</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;"><code>60</code></td><td style="text-align:left;">画像切り替えインターバル時間（分）</td></tr><tr><td style="text-align:left;"><code>liveWallpaperOrder</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;random&quot;</code></td><td style="text-align:left;">切り替え順序 (<code>random</code> / <code>order</code>)</td></tr><tr><td style="text-align:left;"><code>liveWallpaperScaleMode</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;cover&quot;</code></td><td style="text-align:left;">画面フィッティング (<code>cover</code> / <code>fit</code>)</td></tr><tr><td style="text-align:left;"><code>liveWallpaperBackground</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;black&quot;</code></td><td style="text-align:left;">余白背景色 (<code>black</code> / <code>white</code> / <code>blur</code>)</td></tr><tr><td style="text-align:left;"><code>liveWallpaperCrossfade</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">切り替え時のクロスフェードアニメーション</td></tr><tr><td style="text-align:left;"><code>liveWallpaperExcludeSensitive</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">R-18 センシティブ作品の壁紙除外</td></tr></tbody></table><hr><h2 id="ホーム画面ウィジェット" tabindex="-1">ホーム画面ウィジェット <a class="header-anchor" href="#ホーム画面ウィジェット" aria-label="Permalink to &quot;ホーム画面ウィジェット&quot;">​</a></h2><p><code>AppWidgetProvider</code> を継承した 2 種類のホーム画面ウィジェットを提供します。</p><h3 id="_1-イラストウィジェット-illustwidgetprovider-illustwidgetconfigureactivity" tabindex="-1">1. イラストウィジェット (<code>IllustWidgetProvider</code> / <code>IllustWidgetConfigureActivity</code>) <a class="header-anchor" href="#_1-イラストウィジェット-illustwidgetprovider-illustwidgetconfigureactivity" aria-label="Permalink to &quot;1. イラストウィジェット (`IllustWidgetProvider` / `IllustWidgetConfigureActivity`)&quot;">​</a></h3><ul><li><strong>機能</strong>: ブックマーク作品や特定タグのイラストを 2x2 / 4x4 サイズで配置。</li><li><strong>データ保持 (<code>IllustWidgetStore</code>)</strong>: 設定された表示モード、作品 ID、更新タイマーを Preferences に保持。</li><li><strong>タップアクション</strong>: ウィジェットタップ時に Palleria アプリを起動し、該当イラストの詳細画面へ直接ディープリンク遷移。</li></ul><h3 id="_2-ランキングウィジェット-rankingwidgetprovider" tabindex="-1">2. ランキングウィジェット (<code>RankingWidgetProvider</code>) <a class="header-anchor" href="#_2-ランキングウィジェット-rankingwidgetprovider" aria-label="Permalink to &quot;2. ランキングウィジェット (`RankingWidgetProvider`)&quot;">​</a></h3><ul><li><strong>機能</strong>: Pixiv のデイリーランキング TOP 10 作品のサムネイルとタイトルを 4x2 サイズでスライド表示。</li><li><strong>更新ロジック</strong>: <code>WorkManager</code> 定期タスクと連携し、毎日バックグラウンドでランキングデータを最新に更新。</li></ul>',14)])])}const x=e(o,[["render",i]]);export{f as __pageData,x as default};
